function tkWords(text){ return String(text||'').trim().split(/\s+/).filter(Boolean); }
function tkPairCounts(words){
  var c = {};
  for(var i=0;i<words.length;i++){
    var w = words[i];
    for(var j=0;j<w.length-1;j++){
      var k = w[j] + '\u0001' + w[j+1];
      c[k] = (c[k]||0) + 1;
    }
  }
  return c;
}
function tkBestPair(counts){
  var best = null, bestN = 1;
  for(var k in counts){
    if(counts[k] > bestN || (counts[k] === bestN && best !== null && k < best)){
      best = k; bestN = counts[k];
    }
  }
  return best ? { pair: best.split('\u0001'), count: bestN } : null;
}
function tkMergeWord(w, a, b){
  var out = [], i = 0;
  while(i < w.length){
    if(i < w.length-1 && w[i] === a && w[i+1] === b){ out.push(a+b); i += 2; }
    else { out.push(w[i]); i++; }
  }
  return out;
}
function tkTrain(text, numMerges){
  var words = tkWords(text).map(function(w){ return w.split(''); });
  var merges = [];
  for(var m=0;m<numMerges;m++){
    var best = tkBestPair(tkPairCounts(words));
    if(!best || best.count < 2) break;
    merges.push(best.pair);
    for(var i=0;i<words.length;i++) words[i] = tkMergeWord(words[i], best.pair[0], best.pair[1]);
  }
  return merges;
}
function tkEncodeWord(word, merges){
  var w = String(word).split('');
  for(var m=0;m<merges.length;m++) w = tkMergeWord(w, merges[m][0], merges[m][1]);
  return w;
}
function tkEncode(text, merges){
  var out = [];
  var ws = tkWords(text);
  for(var i=0;i<ws.length;i++) out.push(tkEncodeWord(ws[i], merges));
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tkWords:tkWords, tkPairCounts:tkPairCounts, tkBestPair:tkBestPair, tkMergeWord:tkMergeWord, tkTrain:tkTrain, tkEncodeWord:tkEncodeWord, tkEncode:tkEncode };
}
if (typeof window !== 'undefined') {
  window.TokenizeForgePure = { tkWords:tkWords, tkPairCounts:tkPairCounts, tkBestPair:tkBestPair, tkMergeWord:tkMergeWord, tkTrain:tkTrain, tkEncodeWord:tkEncodeWord, tkEncode:tkEncode };
}
